fn is_sorted(arr: &Vec<i32>) -> bool {
    // Iterate through the array, comparing each element with the next one
    for i in 0..arr.len() - 1 {
        if arr[i] > arr[i + 1] {
            return false; // Found a pair that violates the nondecreasing order
        }
    }
    true // If we reach here, the array is sorted
}